package com.badrulamin.University_Management.entity;  import com.fasterxml.jackson.annotation.JsonProperty; import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp;  import java.time.LocalDateTime;  @Entity @Table(name = "application_review") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class ApplicationReview {      @Id     @GeneratedValue(strategy = GenerationType.IDENTITY)     private Long id;      @ManyToOne(fetch = FetchType.EAGER)     @JoinColumn(name = "application_id", nullable = false)     private AdmissionApplication application;      @ManyToOne(fetch = FetchType.EAGER)     @JoinColumn(name = "reviewer_id")     private User reviewer;      @Column(nullable = false)     private String status;      @Column(length = 2000)     private String comments;      @Column(length = 1000)     private String rejectionReason;      private Integer score;      private LocalDateTime reviewedAt;      private Boolean isRecommended;      @Column(updatable = false)     @CreationTimestamp     private LocalDateTime createdAt;      @UpdateTimestamp     private LocalDateTime updatedAt;      @JsonProperty("applicationId")     public Long getApplicationId() {         return application != null ? application.getId() : null;     }      @JsonProperty("applicationId")     public void setApplicationId(Long applicationId) {         if (applicationId != null) {             AdmissionApplication a = new AdmissionApplication();             a.setId(applicationId);             this.application = a;         }     }      @JsonProperty("reviewerId")     public Long getReviewerId() {         return reviewer != null ? reviewer.getId() : null;     }      @JsonProperty("reviewerId")     public void setReviewerId(Long reviewerId) {         if (reviewerId != null) {             User u = new User();             u.setId(reviewerId);             this.reviewer = u;         }     } }